import{newSpecPage}from"@stencil/core/testing";import{ScSubscriptionStatusBadge}from"../sc-subscription-status-badge";const render=async e=>{const t=await newSpecPage({components:[ScSubscriptionStatusBadge],html:"<sc-subscription-status-badge></sc-subscription-status-badge>"});return t.root.subscription=e,await t.waitForChanges(),t.root.shadowRoot.textContent.trim()};describe("sc-subscription-status-badge",(()=>{it("renders",(async()=>{const e=await newSpecPage({components:[ScSubscriptionStatusBadge],html:"<sc-subscription-status-badge></sc-subscription-status-badge>"});expect(e.root).toMatchSnapshot()})),it("says Pausing when a pause is scheduled",(async()=>{expect(await render({status:"active",cancel_at_period_end:1786e6,current_period_end_at:1786e6,restore_at:1817e6})).toBe("Pausing")})),it("says Cancelling when a cancellation is scheduled",(async()=>{expect(await render({status:"active",cancel_at_period_end:1786e6,current_period_end_at:1786e6,restore_at:null})).toBe("Cancelling")})),it("says Paused once the pause has taken effect",(async()=>{expect(await render({status:"canceled",restore_at:1817e6})).toBe("Paused")})),it("says Canceled when there is no restore date",(async()=>{expect(await render({status:"canceled",restore_at:null})).toBe("Canceled")})),it("says Active for a plain active subscription",(async()=>{expect(await render({status:"active",current_period_end_at:1786e6})).toBe("Active")}))}));